import json,re
for step in [0,9,19,29]:
    rows=[json.loads(l) for l in open(f'results/ppo_countdown/val_generations/{step}.jsonl')]
    trailing=0; corr=0; corr_trailing=0; corr_trunc=0
    for r in rows:
        out=r['output']; sc=r['score']
        m=list(re.finditer(r'</answer>',out))
        if m:
            tail=out[m[-1].end():]
            if tail.strip() and tail.strip()!='<|im_end|>':
                trailing+=1
                if sc>0: corr_trailing+=1
        if sc>0:
            corr+=1
            if r['response_length']>=512: corr_trunc+=1
    print(f"step {step}: trailing_after_answer={trailing} correct={corr} correct_trailing={corr_trailing} correct_truncated={corr_trunc}")
    # show a correct long with tail
    for r in rows:
        if r['score']>0:
            m=list(re.finditer(r'</answer>',r['output']))
            if m:
                tail=r['output'][m[-1].end():]
                if tail.strip() and tail.strip()!='<|im_end|>':
                    print('  EXAMPLE tail:',repr(tail[:300]))
                    break
EOF

